import React from 'react';

export default function RecentEventsPanel({
  events = [],
  loading = false,
  error = null,
  onEventClick,
}) {
  return (
    <div className="recent-events-panel">
      <div className="panel-header">
        <h2>최근 탐지 이벤트</h2>
      </div>

      <div className="recent-events-list">
        {loading && <p>최근 이벤트를 불러오는 중...</p>}
        {error && (
          <p style={{ color: 'red' }}>
            최근 이벤트를 불러오는 중 오류가 발생했습니다: {error.message}
          </p>
        )}

        {!loading && !error && events.length === 0 && (
          <p style={{ fontSize: 13, color: '#9ca3af' }}>아직 탐지된 이벤트가 없습니다.</p>
        )}

        {!loading &&
          !error &&
          events.map((ev) => (
            <div
              key={ev.id}
              className="event-item"
              onClick={() => onEventClick?.(ev)}
              style={{ cursor: onEventClick ? 'pointer' : 'default' }}
            >
              <div className="event-main">
                <span className="event-time">{ev.time}</span>
                <span className="event-message">{ev.message}</span>
              </div>
              <div className="event-sub">
                <span className="event-path">{ev.path}</span>
                <span
                  className={
                    'event-level ' +
                    (ev.level === 'danger'
                      ? 'event-level-danger'
                      : ev.level === 'warning'
                      ? 'event-level-warning'
                      : 'event-level-info')
                  }
                >
                  {ev.level === 'danger' ? '위험' : ev.level === 'warning' ? '주의' : '정보'}
                </span>
              </div>
            </div>
          ))}
      </div>
    </div>
  );
}
